CREATE OR REPLACE FUNCTION public.content_pipeline_build_image_generation_contract_v1(p_pipeline_image_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b jsonb;
begin
  select image_brief into b from public."21_content_pipeline_image" where pipeline_image_id=p_pipeline_image_id;
  if not found then raise exception using errcode='P0002',message='CONTENT_PIPELINE_IMAGE_NOT_FOUND'; end if;
  if coalesce(nullif(b->>'contract_version','')::int,4)>=5 then
    return public.content_pipeline_build_image_generation_contract_v5(p_pipeline_image_id);
  end if;
  return public.content_pipeline_build_image_generation_contract_v4_legacy(p_pipeline_image_id);
end
$function$

CREATE OR REPLACE FUNCTION public.content_pipeline_build_image_generation_contract_v4_legacy(p_pipeline_image_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 i public."21_content_pipeline_image"%rowtype; p public."18_content_pipeline"%rowtype;
 b jsonb; inner_b jsonb; c jsonb; v_priority jsonb; v_full boolean; v_gen boolean; v_ai boolean; v_prod_source boolean;
begin
 select * into i from public."21_content_pipeline_image" where pipeline_image_id=p_pipeline_image_id;
 if not found then raise exception using errcode='P0002',message='CONTENT_PIPELINE_IMAGE_NOT_FOUND'; end if;
 select * into p from public."18_content_pipeline" where pipeline_id=i.pipeline_id;
 if not found then raise exception using errcode='P0002',message='CONTENT_PIPELINE_NOT_FOUND'; end if;
 b:=coalesce(i.image_brief,'{}'::jsonb);
 inner_b:=case when jsonb_typeof(b->'image_brief')='object' then b->'image_brief' else b end;
 v_gen:=coalesce(inner_b->>'generation_allowed',b->>'generation_allowed','false')='true';
 v_ai:=coalesce(inner_b->>'generative_edit_allowed',inner_b->>'ai_edit_allowed',b->>'generative_edit_allowed',b->>'ai_edit_allowed','true')='true';
 v_full:=coalesce(inner_b->>'full_generation_allowed',b->>'full_generation_allowed','false')='true';
 v_prod_source:=coalesce(inner_b->>'production_source_required',b->>'production_source_required',inner_b->>'real_source_required',b->>'real_source_required','false')='true';
 if jsonb_typeof(coalesce(inner_b->'source_priority',b->'source_priority'))='array' then
   v_priority:=coalesce(inner_b->'source_priority',b->'source_priority');
 else
   v_priority:='["REAL_SOURCE_DIRECT","REAL_SOURCE_CROP_OR_MARK"]'::jsonb;
   if v_ai then v_priority:=v_priority||'"REAL_SOURCE_AI_EDIT"'::jsonb; end if;
   if v_gen and not v_prod_source then v_priority:=v_priority||'"REFERENCE_BASED_GENERATION"'::jsonb; end if;
   if coalesce(inner_b->>'manual_visual_source_allowed',b->>'manual_visual_source_allowed','false')='true' then v_priority:=v_priority||'"OFFICIAL_PDF_CROP"'::jsonb; end if;
   if v_full then v_priority:=v_priority||'"FULL_AI_GENERATION"'::jsonb; end if;
 end if;
 c:=jsonb_strip_nulls(jsonb_build_object(
 'contract_version',4,'pipeline_image_id',i.pipeline_image_id,'pipeline_id',i.pipeline_id,
 'content_key',p.content_key,'topic_key',p.topic_key,'image_id',i.image_id,'asset_key',i.asset_key,
 'asset_role',coalesce(inner_b->>'asset_role',b->>'asset_role',inner_b->>'role',b->>'role','BODY'),
 'role',coalesce(inner_b->>'visual_role',inner_b->>'role',b->>'role'),
 'subject',inner_b->>'subject','scene',inner_b->'scene',
 'composition_plan',coalesce(inner_b->'composition_plan',b->'composition_plan'),
 'visual_objective',coalesce(inner_b->>'visual_objective',b->>'visual_objective'),
 'user_question_supported',coalesce(inner_b->>'user_question_supported',inner_b->>'user_question',b->>'user_question'),
 'source_strategy',coalesce(inner_b->>'source_strategy',b->>'source_strategy','REFERENCE_FIRST_GENERATIVE'),
 'source_priority',v_priority,
 'generation_allowed',v_gen,
 'reference_based_generation_allowed',coalesce(inner_b->>'reference_based_generation_allowed',b->>'reference_based_generation_allowed','false')='true',
 'real_source_required',v_prod_source,
 'production_source_required',v_prod_source,
 'reference_fact_required',coalesce(inner_b->>'reference_fact_required',b->>'reference_fact_required','true')='true',
 'ai_edit_allowed',v_ai,
 'full_generation_allowed',v_full,
 'production_feasibility',coalesce(inner_b->'production_feasibility',b->'production_feasibility'),
 'production_flexibility',coalesce(inner_b->'production_flexibility',b->'production_flexibility'),
 'annotation_contract',coalesce(inner_b->'annotation_contract',b->'annotation_contract'),
 'pixel_qa_contract',coalesce(inner_b->'pixel_qa_contract',b->'pixel_qa_contract'),
 'qa_criteria',coalesce(inner_b->'qa_criteria',b->'qa_criteria'),
 'visual_context_policy',coalesce(inner_b->'visual_context_policy',b->'visual_context_policy'),
 'visual_evidence_binding',coalesce(inner_b->'visual_evidence_binding',b->'visual_evidence_binding'),
 'people_mode',coalesce(inner_b->>'people_mode',b->>'people_mode','NONE'),
 'guidance_mode',coalesce(inner_b->>'guidance_mode',b->>'guidance_mode'),
 'inspection_target',inner_b->>'inspection_target','inspection_point',inner_b->>'inspection_point',
 'label_text',inner_b->>'label_text','marker_allowed',inner_b->'marker_allowed',
 'must_show',coalesce(inner_b->'must_show','[]'::jsonb),
 'must_not_show',coalesce(inner_b->'must_not_show',inner_b->'prohibited','[]'::jsonb),
 'fact_dependencies',coalesce(inner_b->'fact_dependencies','[]'::jsonb),
 'safety_dependencies',coalesce(inner_b->'safety_dependencies','[]'::jsonb),
 'text_in_image',inner_b->'text_in_image','mobile_requirement',coalesce(inner_b->>'mobile_requirement',b->>'mobile_requirement'),
 'preferred_orientation',inner_b->>'preferred_orientation',
 'alt_text_draft',coalesce(inner_b->>'alt_text_draft',inner_b->>'alt_draft',inner_b->>'alt',b->>'alt_text_draft',b->>'alt_draft',b->>'alt'),
 'content_isolation_rule','Use only this generation contract for this image. Do not inherit subject, scene, objects, text, layout, prior generated image, or visual prompt from any other content or image task.'
 ));
 if coalesce(c->>'content_key','')='' or coalesce(c->>'image_id','')='' or coalesce(c->>'asset_key','')='' then
 raise exception using errcode='22023',message='CONTENT_PIPELINE_IMAGE_CONTRACT_INCOMPLETE'; end if;
 return c;
end $function$

CREATE OR REPLACE FUNCTION public.content_pipeline_build_image_generation_contract_v5(p_pipeline_image_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  i public."21_content_pipeline_image"%rowtype;
  b jsonb;
begin
  select * into i from public."21_content_pipeline_image" where pipeline_image_id=p_pipeline_image_id;
  if not found then raise exception using errcode='P0002',message='CONTENT_PIPELINE_IMAGE_NOT_FOUND'; end if;
  b:=coalesce(i.image_brief,'{}'::jsonb);
  if coalesce((b->>'contract_version')::int,0)<>5 then raise exception using errcode='22023',message='CONTENT_PIPELINE_CONTRACT_V5_REQUIRED'; end if;
  if (public.content_pipeline_validate_image_brief_v5(b)->>'status')<>'PASS' then raise exception using errcode='22023',message='CONTENT_PIPELINE_IMAGE_V5_INVALID'; end if;
  return jsonb_strip_nulls(jsonb_build_object(
    'contract_version',5,
    'image_id',coalesce(b->>'image_id',i.image_id),
    'asset_role',coalesce(b->>'asset_role','BODY'),
    'user_question',b->>'user_question',
    'visual_objective',b->>'visual_objective',
    'must_show',coalesce(b->'must_show','[]'::jsonb),
    'must_not_show',coalesce(b->'must_not_show','[]'::jsonb),
    'evidence_requirement',b->'evidence_requirement',
    'alt_text_draft',coalesce(b->>'alt_text_draft',b->>'alt_draft',b->>'alt')
  ));
end
$function$

CREATE OR REPLACE FUNCTION public.content_pipeline_sync_images_v1(p_pipeline_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public."18_content_pipeline"%rowtype;
  v_items jsonb; v_item jsonb; v_ord int := 0; v_asset text; v_image text;
  v_count int; v_keys text[] := array[]::text[]; v_pid bigint; v_contract jsonb; v_hash text; v_validation jsonb;
  v_existing_status text; v_existing_brief jsonb; v_existing_image text; v_contract_version int; v_max_version int:=4;
begin
  select * into p from public."18_content_pipeline" where pipeline_id=p_pipeline_id for update;
  if not found then raise exception 'CONTENT_PIPELINE_NOT_FOUND'; end if;
  if p.ownership_state <> 'CLAIMED' or p.stage not in ('DRAFTED','VISUAL','IMAGE_READY') then raise exception 'CONTENT_PIPELINE_IMAGES_NOT_AVAILABLE'; end if;
  v_items := case when jsonb_typeof(p.writer_artifact->'image_briefs')='array' then p.writer_artifact->'image_briefs'
    when jsonb_typeof(p.writer_artifact->'image_manifest')='array' then p.writer_artifact->'image_manifest' else '[]'::jsonb end;
  if jsonb_array_length(v_items)=0 then raise exception 'CONTENT_PIPELINE_NO_IMAGES_UNSUPPORTED'; end if;
  if exists(select 1 from public."21_content_pipeline_image" where pipeline_id=p_pipeline_id and status='PROCESSING') then raise exception 'CONTENT_PIPELINE_IMAGE_REPLAN_PROCESSING'; end if;

  for v_item in select value from jsonb_array_elements(v_items) loop
    v_contract_version:=coalesce(nullif(v_item->>'contract_version','')::int,4);
    v_max_version:=greatest(v_max_version,v_contract_version);
    if v_item->'contract_version'='5'::jsonb then
      if v_item->>'asset_role'='THUMBNAIL' then v_asset:='thumbnail';
      elsif v_item->>'asset_role' in('HERO','THUMBNAIL_HERO') then v_asset:='hero';
      else
       -- Preserve a compatible existing task identity; new BODY keys are allocated server-side.
       select asset_key into v_asset from public."21_content_pipeline_image"
       where pipeline_id=p_pipeline_id and image_id=v_item->>'image_id' and asset_key ~ '^body-[0-9]{2}$'
       order by pipeline_image_id limit 1;
       if v_asset is null then
        select 'body-'||lpad(n::text,2,'0') into v_asset from generate_series(1,99) n
        where not ('body-'||lpad(n::text,2,'0'))=any(v_keys)
        and not exists(select 1 from public."21_content_pipeline_image" old where old.pipeline_id=p_pipeline_id and old.asset_key='body-'||lpad(n::text,2,'0'))
        order by n limit 1;
        if v_asset is null then raise exception 'CONTENT_PIPELINE_BODY_ASSET_CAPACITY_EXCEEDED';end if;
       end if;
      end if;
    else
    v_asset:=coalesce(v_item->>'asset_key',case when v_ord=0 then 'thumbnail' when v_ord=1 then 'hero' else 'body-'||lpad((v_ord-1)::text,2,'0') end);
    end if;
    v_image:=coalesce(nullif(v_item->>'image_id',''),'IMAGE_'||lpad((v_ord+1)::text,2,'0'));
    if v_asset !~ '^(thumbnail|hero|body-[0-9]{2})$' or v_asset=any(v_keys) then raise exception 'CONTENT_PIPELINE_INVALID_OR_DUPLICATE_ASSET_KEY'; end if;
    v_keys:=array_append(v_keys,v_asset);

    select status,image_brief,image_id into v_existing_status,v_existing_brief,v_existing_image
    from public."21_content_pipeline_image" where pipeline_id=p_pipeline_id and asset_key=v_asset;

    if v_existing_status in ('DONE','READY_FOR_UPLOAD') then
      if v_existing_brief is distinct from v_item or v_existing_image is distinct from v_image then raise exception 'CONTENT_PIPELINE_DONE_IMAGE_REPLAN_CONFLICT'; end if;
      v_ord:=v_ord+1; continue;
    end if;

    v_validation:=public.content_pipeline_validate_image_brief_feasibility_v1(v_item);
    if v_validation->>'status'<>'PASS' then raise exception using errcode='22023',message='CONTENT_PIPELINE_IMAGE_FEASIBILITY_FAILED',detail=v_validation::text; end if;

    insert into public."21_content_pipeline_image"(pipeline_id,image_id,asset_key,ordinal,image_brief)
      values(p_pipeline_id,v_image,v_asset,v_ord,v_item)
    on conflict (pipeline_id,asset_key) do update set
      image_id=excluded.image_id,ordinal=excluded.ordinal,image_brief=excluded.image_brief,
      status=case when public."21_content_pipeline_image".status in ('DONE','READY_FOR_UPLOAD') then public."21_content_pipeline_image".status
        when public."21_content_pipeline_image".image_brief is distinct from excluded.image_brief or public."21_content_pipeline_image".status='CANCELLED' then 'PENDING'
        else public."21_content_pipeline_image".status end,
      retry_action=case when public."21_content_pipeline_image".image_brief is distinct from excluded.image_brief or public."21_content_pipeline_image".status='CANCELLED' then null else public."21_content_pipeline_image".retry_action end,
      next_eligible_at=case when public."21_content_pipeline_image".image_brief is distinct from excluded.image_brief or public."21_content_pipeline_image".status='CANCELLED' then null else public."21_content_pipeline_image".next_eligible_at end,
      staging_asset=case when public."21_content_pipeline_image".status not in ('DONE','READY_FOR_UPLOAD') and public."21_content_pipeline_image".image_brief is distinct from excluded.image_brief then null else public."21_content_pipeline_image".staging_asset end,
      staging_input=case when public."21_content_pipeline_image".status not in ('DONE','READY_FOR_UPLOAD') and public."21_content_pipeline_image".image_brief is distinct from excluded.image_brief then null else public."21_content_pipeline_image".staging_input end,
      failure_stage=case when public."21_content_pipeline_image".status not in ('DONE','READY_FOR_UPLOAD') and public."21_content_pipeline_image".image_brief is distinct from excluded.image_brief then null else public."21_content_pipeline_image".failure_stage end,
      failure_code=case when public."21_content_pipeline_image".status not in ('DONE','READY_FOR_UPLOAD') and public."21_content_pipeline_image".image_brief is distinct from excluded.image_brief then null else public."21_content_pipeline_image".failure_code end,
      last_error=case when public."21_content_pipeline_image".status not in ('DONE','READY_FOR_UPLOAD') and public."21_content_pipeline_image".image_brief is distinct from excluded.image_brief then null else public."21_content_pipeline_image".last_error end,
      updated_at=now()
    returning pipeline_image_id into v_pid;

    v_contract:=public.content_pipeline_build_image_generation_contract_v1(v_pid);
    if coalesce((v_contract->>'contract_version')::int,4)<5 and coalesce(v_contract->'production_feasibility'->>'status','')<>'PASS' then raise exception 'CONTENT_PIPELINE_CONTRACT_FEASIBILITY_NOT_PASS'; end if;
    v_hash:=encode(extensions.digest(convert_to(v_contract::text,'UTF8'),'sha256'),'hex');
    update public."21_content_pipeline_image" set generation_contract=v_contract,generation_contract_hash=v_hash,updated_at=now() where pipeline_image_id=v_pid;
    v_ord:=v_ord+1;
  end loop;

  if exists(select 1 from public."21_content_pipeline_image" where pipeline_id=p_pipeline_id and asset_key <> all(v_keys) and status in ('DONE','READY_FOR_UPLOAD')) then raise exception 'CONTENT_PIPELINE_DONE_IMAGE_REMOVAL_CONFLICT'; end if;
  update public."21_content_pipeline_image" set status='CANCELLED',retry_action='WRITER_REPLANNED',claimed_by=null,claim_token=null,claimed_at=null,claim_expires_at=null,next_eligible_at=null,updated_at=now()
    where pipeline_id=p_pipeline_id and asset_key <> all(v_keys) and status not in ('CANCELLED','DONE','READY_FOR_UPLOAD');
  select count(*) into v_count from public."21_content_pipeline_image" where pipeline_id=p_pipeline_id and status<>'CANCELLED';
  return jsonb_build_object('pipelineId',p_pipeline_id,'requiredImageCount',v_count,'productionFeasibility','PASS','contractVersion',v_max_version);
end
$function$

CREATE OR REPLACE FUNCTION public.content_pipeline_validate_image_brief_feasibility_v1(p_brief jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if p_brief->'contract_version'='5'::jsonb then
    return public.content_pipeline_validate_image_brief_v5(p_brief);
  end if;
  if p_brief ? 'contract_version' and coalesce(p_brief->>'contract_version','') not in('1','2','3','4') then return jsonb_build_object('status','FAIL','reasons',jsonb_build_array('UNSUPPORTED_CONTRACT_VERSION'));end if;
  return public.content_pipeline_validate_image_brief_feasibility_v4_legacy(p_brief);
end
$function$

CREATE OR REPLACE FUNCTION public.content_pipeline_validate_image_brief_feasibility_v4_legacy(p_brief jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  pf jsonb; flex jsonb; pqa jsonb; reasons jsonb := '[]'::jsonb; must_count int := 0; qa_count int := 0;
  full_allowed boolean := false; ai_edit boolean := true; pm text; ms jsonb; mns jsonb; qrv jsonb;
  ac jsonb; vcp jsonb; pqa_ac jsonb; annotation_required boolean := false; annotation_decision text;
begin
  if p_brief is null or jsonb_typeof(p_brief) <> 'object' then
    return jsonb_build_object('status','FAIL','reasons',jsonb_build_array('IMAGE_BRIEF_MISSING'));
  end if;
  pf := p_brief->'production_feasibility';
  flex := p_brief->'production_flexibility';
  pqa := p_brief->'pixel_qa_contract';
  pm := coalesce(p_brief->>'people_mode','NONE');
  ms := coalesce(p_brief->'must_show','[]'::jsonb);
  mns := coalesce(p_brief->'must_not_show','[]'::jsonb);
  ac := coalesce(p_brief->'annotation_contract','{}'::jsonb);
  vcp := coalesce(p_brief->'visual_context_policy','{}'::jsonb);
  annotation_required := coalesce(ac->>'required','false')='true';
  annotation_decision := coalesce(vcp->>'annotation_decision','');

  if jsonb_typeof(pf) <> 'object' or coalesce(pf->>'status','') <> 'PASS' then reasons := reasons || '"PRODUCTION_FEASIBILITY_NOT_PASS"'::jsonb; end if;
  if coalesce(pf->>'contract_consistency','false') <> 'true' then reasons := reasons || '"CONTRACT_CONSISTENCY_NOT_PASS"'::jsonb; end if;
  if coalesce(pf->>'people_action_consistency','false') <> 'true' then reasons := reasons || '"PEOPLE_ACTION_CONSISTENCY_NOT_PASS"'::jsonb; end if;
  if coalesce(pf->>'source_strategy_feasible','false') <> 'true' then reasons := reasons || '"SOURCE_STRATEGY_NOT_FEASIBLE"'::jsonb; end if;
  if coalesce(pf->>'pixel_verifiable','false') <> 'true' then reasons := reasons || '"PIXEL_VERIFIABLE_NOT_PASS"'::jsonb; end if;
  if coalesce(pf->>'generation_safe','false') <> 'true' then reasons := reasons || '"GENERATION_SAFE_NOT_PASS"'::jsonb; end if;
  if coalesce(pf->>'single_source_satisfiable','false') <> 'true' then reasons := reasons || '"SINGLE_SOURCE_NOT_SATISFIABLE"'::jsonb; end if;
  if coalesce(pf->>'multi_source_composition_required','false') = 'true' then reasons := reasons || '"MULTI_SOURCE_COMPOSITION_REQUIRED"'::jsonb; end if;
  if coalesce(pf->>'mobile_single_question','false') <> 'true' then reasons := reasons || '"MOBILE_SINGLE_QUESTION_NOT_CONFIRMED"'::jsonb; end if;
  if jsonb_typeof(flex) <> 'object' then reasons := reasons || '"PRODUCTION_FLEXIBILITY_MISSING"'::jsonb; end if;
  if coalesce(p_brief->>'manual_visual_source_allowed','false') = 'true' then reasons := reasons || '"MANUAL_PDF_VISUAL_NOT_ALLOWED"'::jsonb; end if;

  if annotation_required and annotation_decision='NOT_REQUIRED' then reasons := reasons || '"ANNOTATION_POLICY_CONTRADICTION"'::jsonb; end if;
  if (not annotation_required) and annotation_decision='REQUIRED' then reasons := reasons || '"ANNOTATION_POLICY_CONTRADICTION"'::jsonb; end if;

  if jsonb_typeof(ms)='array' then must_count:=jsonb_array_length(ms); end if;
  if must_count > 4 then reasons := reasons || '"MUST_SHOW_TOO_COMPLEX"'::jsonb; end if;
  if coalesce(p_brief->>'asset_role','') in ('HERO','THUMBNAIL_HERO','THUMBNAIL') and must_count > 3 then reasons := reasons || '"HERO_MUST_SHOW_TOO_COMPLEX"'::jsonb; end if;

  if jsonb_typeof(pqa) <> 'object' then
    reasons := reasons || '"PIXEL_QA_CONTRACT_MISSING"'::jsonb;
  else
    qrv := coalesce(pqa->'required_visible','[]'::jsonb);
    if jsonb_typeof(qrv)<>'array' or jsonb_array_length(qrv)=0 then reasons := reasons || '"PIXEL_QA_CORE_REQUIRED_MISSING"'::jsonb;
    else
      qa_count := jsonb_array_length(qrv);
      if exists (select 1 from jsonb_array_elements_text(qrv) q(value) where not exists (select 1 from jsonb_array_elements_text(ms) m(value) where m.value=q.value)) then
        reasons := reasons || '"PIXEL_QA_REQUIRED_NOT_SUBSET_OF_MUST_SHOW"'::jsonb;
      end if;
      if qa_count > 2 and coalesce(p_brief->>'qa_core_overflow_allowed','false')<>'true' then reasons := reasons || '"PIXEL_QA_CORE_TOO_COMPLEX"'::jsonb; end if;
    end if;
    if coalesce(pqa->'prohibited_visible','[]'::jsonb) is distinct from mns then reasons := reasons || '"PIXEL_QA_PROHIBITED_VISIBLE_MISMATCH"'::jsonb; end if;
    if coalesce(pqa->>'people_mode','') <> pm then reasons := reasons || '"PIXEL_QA_PEOPLE_MODE_MISMATCH"'::jsonb; end if;
    if coalesce(pqa->>'semantic_objective_is_gate','true') <> 'false' then reasons := reasons || '"SEMANTIC_OBJECTIVE_MUST_NOT_BE_PIXEL_GATE"'::jsonb; end if;
    pqa_ac := coalesce(pqa->'annotation_contract','{}'::jsonb);
    if coalesce(pqa_ac->>'required','false') <> coalesce(ac->>'required','false') then reasons := reasons || '"PIXEL_QA_ANNOTATION_CONTRACT_MISMATCH"'::jsonb; end if;
  end if;

  if lower(ms::text) ~ '(상황|맥락|스타터 반응|열간 상태|판단|여부|흐름)' then reasons := reasons || '"MUST_SHOW_NOT_PIXEL_VERIFIABLE"'::jsonb; end if;
  if jsonb_typeof(ms)='array' and jsonb_typeof(mns)='array' and exists (
    select 1 from jsonb_array_elements_text(ms) s(value)
    join jsonb_array_elements_text(mns) n(value) on lower(btrim(s.value))=lower(btrim(n.value))
    where length(btrim(s.value))>0
  ) then reasons:=reasons||'"MUST_SHOW_FORBIDDEN_CONTRADICTION"'::jsonb; end if;

  if ((ms::text ilike '%Owner%Manual%' or ms::text ilike '%설명서%' or ms::text ilike '%매뉴얼%')
      and (ms::text ilike '%계기판%' or ms::text ilike '%오토바이%' or ms::text ilike '%차량%')
      and coalesce(pf->>'single_source_satisfiable','false')='true'
      and coalesce(pf->>'multi_source_composition_required','false')='false'
      and coalesce(p_brief->>'single_scene_composition_allowed','false')<>'true') then
    reasons := reasons || '"MULTI_MEDIA_SINGLE_SOURCE_AMBIGUOUS"'::jsonb;
  end if;

  full_allowed := coalesce(p_brief->>'full_generation_allowed','false')='true';
  if coalesce(pf->>'full_generation_required','false')='true' and not full_allowed then reasons := reasons || '"FULL_GENERATION_CONFLICT"'::jsonb; end if;
  ai_edit := coalesce(p_brief->>'generative_edit_allowed',p_brief->>'ai_edit_allowed','true')='true';
  if jsonb_typeof(p_brief->'source_priority')='array' then
    if not full_allowed and (p_brief->'source_priority') ? 'FULL_AI_GENERATION' then reasons := reasons || '"FULL_AI_PRIORITY_NOT_ALLOWED"'::jsonb; end if;
    if not ai_edit and (p_brief->'source_priority') ? 'REAL_SOURCE_AI_EDIT' then reasons := reasons || '"AI_EDIT_PRIORITY_NOT_ALLOWED"'::jsonb; end if;
  end if;
  if jsonb_typeof(flex)='object' then
    if coalesce(flex->>'exact_source_required','false')='true' and coalesce(p_brief->>'production_source_required','false')<>'true' then reasons := reasons || '"EXACT_SOURCE_WITHOUT_PRODUCTION_SOURCE"'::jsonb; end if;
    if coalesce(flex->>'exact_text_required','false')='true' and coalesce(p_brief->>'production_source_required','false')<>'true' then reasons := reasons || '"EXACT_TEXT_REQUIRES_PRODUCTION_SOURCE"'::jsonb; end if;
  end if;
  if coalesce(flex->>'exact_source_required','false')='true' and
     (coalesce(pf->>'source_evidence_url','') !~ '^https://' or coalesce(pf->>'source_evidence_verified','false')<>'true') then
    reasons:=reasons||'"EXACT_SOURCE_EVIDENCE_REQUIRED"'::jsonb;
  end if;

  return jsonb_build_object('status',case when jsonb_array_length(reasons)=0 then 'PASS' else 'FAIL' end,'reasons',reasons,'mustShowCount',must_count,'qaCoreCount',qa_count,'validatedAt',now());
end $function$

CREATE OR REPLACE FUNCTION public.content_pipeline_validate_visual_contract_v5(p_contract jsonb, p_allow_metadata boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare reasons jsonb:='[]'; k text; item jsonb; refs jsonb; e jsonb; allowed text[]; people_required boolean; people_forbidden boolean;
begin
 if jsonb_typeof(p_contract) is distinct from 'object' then return jsonb_build_object('status','FAIL','reasons',jsonb_build_array('V5_OBJECT_REQUIRED'));end if;
 allowed:=array['contract_version','image_id','asset_role','user_question','visual_objective','must_show','must_not_show','evidence_requirement','alt_text_draft'];
 if p_allow_metadata then allowed:=allowed||array['pipeline_image_id','pipeline_id','content_key','topic_key','asset_key'];end if;
 if exists(select 1 from jsonb_object_keys(p_contract) x where not x=any(allowed)) then reasons:=reasons||'"V5_UNKNOWN_FIELD"'::jsonb;end if;
 if p_contract->'contract_version' is distinct from '5'::jsonb then reasons:=reasons||'"V5_VERSION_REQUIRED"'::jsonb;end if;
 foreach k in array array['image_id','user_question','visual_objective','alt_text_draft'] loop
  if jsonb_typeof(p_contract->k) is distinct from 'string' or btrim(coalesce(p_contract->>k,''))='' or length(coalesce(p_contract->>k,'')) not between 1 and (case when k='image_id' then 100 when k='user_question' then 500 when k='visual_objective' then 1000 else 300 end) then reasons:=reasons||to_jsonb('V5_INVALID_'||upper(k));end if;
 end loop;
 if coalesce(p_contract->>'image_id','') !~ '^IMG_[0-9]{2,}$' then reasons:=reasons||'"V5_IMAGE_ID_INVALID"'::jsonb;end if;
 if p_contract->>'asset_role' is null or p_contract->>'asset_role' not in('THUMBNAIL','HERO','THUMBNAIL_HERO','BODY') then reasons:=reasons||'"V5_ASSET_ROLE_INVALID"'::jsonb;end if;
 foreach k in array array['must_show','must_not_show'] loop
  if jsonb_typeof(p_contract->k) is distinct from 'array' then reasons:=reasons||to_jsonb('V5_INVALID_'||upper(k));
  else
   if jsonb_array_length(p_contract->k)>(case when k='must_show' then 8 else 12 end) or (k='must_show' and jsonb_array_length(p_contract->k)=0) then reasons:=reasons||to_jsonb('V5_INVALID_'||upper(k)||'_COUNT');end if;
   for item in select value from jsonb_array_elements(p_contract->k) loop
    if jsonb_typeof(item) is distinct from 'string' or btrim(coalesce(item#>>'{}',''))='' or length(item#>>'{}') not between 1 and 500 then reasons:=reasons||to_jsonb('V5_INVALID_'||upper(k)||'_ITEM');end if;
   end loop;
   if (select count(*) from jsonb_array_elements(p_contract->k))<>(select count(distinct lower(btrim(value#>>'{}'))) from jsonb_array_elements(p_contract->k)) then reasons:=reasons||to_jsonb('V5_DUPLICATE_'||upper(k));end if;
  end if;
 end loop;
 if jsonb_typeof(p_contract->'must_show')='array' and jsonb_typeof(p_contract->'must_not_show')='array' then
  if exists(select 1 from jsonb_array_elements_text(p_contract->'must_show') s join jsonb_array_elements_text(p_contract->'must_not_show') n on lower(btrim(s.value))=lower(btrim(n.value))) then reasons:=reasons||'"V5_VISIBLE_CONTRADICTION"'::jsonb;end if;
  -- Whole-person requirement only. Partial hands/arms are compatible with people-forbidden framing.
  people_required:=lower((p_contract->'must_show')::text) ~ '(사람|라이더|정비사|운전자|배달원|승객|\\m(person|people|rider|mechanic|driver|motorcyclist|passenger)\\M)';
  people_forbidden:=exists(select 1 from jsonb_array_elements_text(p_contract->'must_not_show') n where lower(btrim(n.value)) in ('사람','사람 없음','person','people','no people','no person'));
  if people_required and people_forbidden then reasons:=reasons||'"V5_PEOPLE_CONTRADICTION"'::jsonb;end if;
 end if;
 e:=p_contract->'evidence_requirement';
 if jsonb_typeof(e) is distinct from 'object' then reasons:=reasons||'"V5_EVIDENCE_REQUIREMENT_INVALID"'::jsonb;
 else
  if exists(select 1 from jsonb_object_keys(e) x where x not in ('level','fact_ids','evidence_ref')) then reasons:=reasons||'"V5_EVIDENCE_UNKNOWN_FIELD"'::jsonb;end if;
  if e->>'level' is null or e->>'level' not in('NONE','REFERENCE','REQUIRED') then reasons:=reasons||'"V5_EVIDENCE_LEVEL_INVALID"'::jsonb;end if;
  if e ? 'fact_ids' then
   if jsonb_typeof(e->'fact_ids') is distinct from 'array' then reasons:=reasons||'"V5_FACT_IDS_INVALID"'::jsonb;
   else
    if jsonb_array_length(e->'fact_ids')>20 then reasons:=reasons||'"V5_FACT_IDS_TOO_MANY"'::jsonb;end if;
    if (select count(*) from jsonb_array_elements(e->'fact_ids'))<>(select count(distinct value) from jsonb_array_elements(e->'fact_ids')) then reasons:=reasons||'"V5_DUPLICATE_FACT_IDS"'::jsonb;end if;
    for item in select value from jsonb_array_elements(e->'fact_ids') loop
     if jsonb_typeof(item) is distinct from 'string' or coalesce(item#>>'{}','') !~ '^CF[1-9][0-9]*$' then reasons:=reasons||'"V5_FACT_ID_INVALID"'::jsonb;end if;
    end loop;
   end if;
  end if;
  if e ? 'evidence_ref' then
   refs:=e->'evidence_ref';
   if jsonb_typeof(refs) is distinct from 'array' then reasons:=reasons||'"V5_EVIDENCE_REF_INVALID"'::jsonb;
   else
    if jsonb_array_length(refs)>4 then reasons:=reasons||'"V5_EVIDENCE_REF_TOO_MANY"'::jsonb;end if;
    for item in select value from jsonb_array_elements(refs) loop
     if jsonb_typeof(item) is distinct from 'object' then reasons:=reasons||'"V5_EVIDENCE_REF_ITEM_INVALID"'::jsonb;
     else
      if exists(select 1 from jsonb_object_keys(item) x where x not in('source_ref','model_scope','supports')) then reasons:=reasons||'"V5_EVIDENCE_REF_UNKNOWN_FIELD"'::jsonb;end if;
      if jsonb_typeof(item->'source_ref') is distinct from 'string' or length(coalesce(item->>'source_ref',''))>2000 or coalesce(item->>'source_ref','') !~ '^https://[^[:space:]]+$' then reasons:=reasons||'"V5_EVIDENCE_SOURCE_REF_INVALID"'::jsonb;end if;
      foreach k in array array['model_scope','supports'] loop
       if item ? k and (jsonb_typeof(item->k) is distinct from 'string' or btrim(coalesce(item->>k,''))='' or length(coalesce(item->>k,'')) not between 1 and (case when k='model_scope' then 500 else 1000 end)) then reasons:=reasons||to_jsonb('V5_EVIDENCE_'||upper(k)||'_INVALID');end if;
      end loop;
     end if;
    end loop;
   end if;
  end if;
 end if;
 return jsonb_build_object('status',case when jsonb_array_length(reasons)=0 then 'PASS' else 'FAIL' end,'reasons',reasons,'validationScope','SEMANTIC_SCHEMA_AND_BASIC_CONSISTENCY','pixelsInspected',false);
end $function$
